@using sv_e7ca8a99a4d4400685db26a14460ca3c.Services

<div class="change-password-panel">
    <button class="panel-toggle" @onclick="() => _isExpanded = !_isExpanded">
        <span class="toggle-icon">@(_isExpanded ? "▼" : "▶")</span>
        Change Password
    </button>

    @if (_isExpanded)
    {
        <div class="panel-content">
            @if (_errorMessage is not null)
            {
                <div class="toast error">@_errorMessage</div>
            }
            @if (_successMessage is not null)
            {
                <div class="toast success">@_successMessage</div>
            }

            <div class="form-group">
                <label for="currentPassword">Current Password</label>
                <input id="currentPassword" type="password" @bind="_currentPassword" class="form-control" />
            </div>

            <div class="form-group">
                <label for="newPassword">New Password</label>
                <input id="newPassword" type="password" @bind="_newPassword" class="form-control" />
            </div>

            <div class="form-group">
                <label for="confirmPassword">Confirm Password</label>
                <input id="confirmPassword" type="password" @bind="_confirmPassword" class="form-control" />
            </div>

            <button class="btn btn-primary" @onclick="UpdatePassword">Update Password</button>
        </div>
    }
</div>

@code {
    [Parameter] public EventCallback<(string Current, string New)> OnChangePassword { get; set; }

    private bool _isExpanded;
    private string _currentPassword = "";
    private string _newPassword = "";
    private string _confirmPassword = "";
    private string? _errorMessage;
    private string? _successMessage;

    private async Task UpdatePassword()
    {
        _errorMessage = null;
        _successMessage = null;

        if (string.IsNullOrWhiteSpace(_currentPassword) || string.IsNullOrWhiteSpace(_newPassword))
        {
            _errorMessage = "All password fields are required.";
            return;
        }

        if (_newPassword != _confirmPassword)
        {
            _errorMessage = "New password and confirmation do not match.";
            return;
        }

        await OnChangePassword.InvokeAsync((_currentPassword, _newPassword));
        _currentPassword = "";
        _newPassword = "";
        _confirmPassword = "";
        _successMessage = "Password updated successfully!";
    }
}

@using sv_e7ca8a99a4d4400685db26a14460ca3c.Services

<div class="active-sessions">
    <h4>Active Sessions</h4>

    @if (_confirmRevokeId is not null)
    {
        <div class="confirmation-dialog">
            <p>Are you sure you want to revoke this session?</p>
            <div class="dialog-actions">
                <button class="btn btn-danger" @onclick="ConfirmRevoke">Yes, Revoke</button>
                <button class="btn btn-secondary" @onclick="() => _confirmRevokeId = null">Cancel</button>
            </div>
        </div>
    }

    <table class="sessions-table">
        <thead>
            <tr>
                <th>Device</th>
                <th>Location</th>
                <th>Last Active</th>
                <th>Actions</th>
            </tr>
        </thead>
        <tbody>
            @foreach (var session in Sessions)
            {
                <tr>
                    <td>@session.Device</td>
                    <td>@session.Location</td>
                    <td>@FormatLastActive(session.LastActive)</td>
                    <td>
                        @if (session.Id != CurrentSessionId)
                        {
                            <button class="btn btn-sm btn-danger" @onclick="() => _confirmRevokeId = session.Id">
                                Revoke
                            </button>
                        }
                        else
                        {
                            <span class="current-badge">Current</span>
                        }
                    </td>
                </tr>
            }
        </tbody>
    </table>
</div>

@code {
    [Parameter] public List<ActiveSession> Sessions { get; set; } = new();
    [Parameter] public string CurrentSessionId { get; set; } = "sess-1";
    [Parameter] public EventCallback<string> OnRevoke { get; set; }

    private string? _confirmRevokeId;

    private async Task ConfirmRevoke()
    {
        if (_confirmRevokeId is not null)
        {
            await OnRevoke.InvokeAsync(_confirmRevokeId);
            _confirmRevokeId = null;
        }
    }

    private static string FormatLastActive(DateTime lastActive)
    {
        var diff = DateTime.UtcNow - lastActive;
        if (diff.TotalMinutes < 60) return $"{(int)diff.TotalMinutes} min ago";
        if (diff.TotalHours < 24) return $"{(int)diff.TotalHours} hours ago";
        return $"{(int)diff.TotalDays} days ago";
    }
}

@using sv_e7ca8a99a4d4400685db26a14460ca3c.Services

<div class="security-section">
    <h3>Security Settings</h3>

    <ChangePasswordPanel OnChangePassword="HandleChangePassword" />

    <div class="two-factor-section">
        <h4>Two-Factor Authentication</h4>
        <div class="two-factor-toggle">
            <label class="toggle-label">
                <input type="checkbox" checked="@_twoFactorEnabled"
                       @onchange="(e) => _twoFactorEnabled = (bool)(e.Value ?? false)"
                       class="toggle-input" />
                <span class="toggle-switch"></span>
                Enable Two-Factor Authentication
            </label>
            <span class="status-indicator @(_twoFactorEnabled ? "status-enabled" : "status-disabled")">
                @(_twoFactorEnabled ? "✓ Enabled" : "✗ Disabled")
            </span>
        </div>
        @if (Security?.LastPasswordChange is not null)
        {
            <p class="last-changed">Last password change: @Security.LastPasswordChange.Value.ToString("MMMM dd, yyyy")</p>
        }
    </div>

    <ActiveSessionsTable Sessions="@(Security?.Sessions ?? new())"
                         OnRevoke="HandleRevoke" />
</div>

@code {
    [Parameter] public SecuritySettings? Security { get; set; }
    [Parameter] public EventCallback<(string Current, string New)> OnChangePassword { get; set; }
    [Parameter] public EventCallback<string> OnRevokeSession { get; set; }

    private bool _twoFactorEnabled;

    protected override void OnParametersSet()
    {
        if (Security is not null)
        {
            _twoFactorEnabled = Security.TwoFactorEnabled;
        }
    }

    private async Task HandleChangePassword((string Current, string New) passwords)
    {
        await OnChangePassword.InvokeAsync(passwords);
    }

    private async Task HandleRevoke(string sessionId)
    {
        await OnRevokeSession.InvokeAsync(sessionId);
    }
}

@using sv_e7ca8a99a4d4400685db26a14460ca3c.Services

<div class="appearance-section">
    <h3>Appearance Settings</h3>

    <div class="form-group">
        <label>Theme</label>
        <div class="radio-group">
            @foreach (var theme in _themes)
            {
                <label class="radio-label">
                    <input type="radio" name="theme" value="@theme"
                           checked="@(_selectedTheme == theme)"
                           @onchange="() => _selectedTheme = theme" />
                    @theme
                </label>
            }
        </div>
    </div>

    <div class="form-group">
        <label>Font Size</label>
        <div class="radio-group">
            @foreach (var size in _fontSizes)
            {
                <label class="radio-label">
                    <input type="radio" name="fontSize" value="@size"
                           checked="@(_selectedFontSize == size)"
                           @onchange="() => _selectedFontSize = size" />
                    @size
                </label>
            }
        </div>
    </div>

    <div class="form-group">
        <label for="language">Language</label>
        <select id="language" @bind="_selectedLanguage" class="form-control">
            @foreach (var lang in _languages)
            {
                <option value="@lang">@lang</option>
            }
        </select>
    </div>

    <div class="toggle-group">
        <label class="toggle-label">
            <input type="checkbox" @bind="_compactMode" class="toggle-input" />
            <span class="toggle-switch"></span>
            Compact Mode
        </label>
    </div>

    <div class="live-preview" style="@GetPreviewStyle()">
        <h4>Live Preview</h4>
        <p>This is how your content will look with the selected settings.</p>
        <p>Theme: @_selectedTheme | Font: @_selectedFontSize | Language: @_selectedLanguage</p>
        @if (_compactMode)
        {
            <p><em>Compact mode is enabled — reduced spacing and smaller elements.</em></p>
        }
    </div>

    <div class="form-actions">
        <button class="btn btn-primary" @onclick="Save">Save</button>
    </div>
</div>

@code {
    [Parameter] public AppearanceSettings? Settings { get; set; }
    [Parameter] public EventCallback<AppearanceSettings> OnSave { get; set; }

    private string _selectedTheme = "Light";
    private string _selectedFontSize = "Medium";
    private string _selectedLanguage = "English";
    private bool _compactMode;

    private readonly string[] _themes = { "Light", "Dark", "System" };
    private readonly string[] _fontSizes = { "Small", "Medium", "Large" };
    private readonly string[] _languages = { "English", "Spanish", "French", "German", "Japanese", "Chinese" };

    protected override void OnParametersSet()
    {
        if (Settings is not null)
        {
            _selectedTheme = Settings.Theme;
            _selectedFontSize = Settings.FontSize;
            _selectedLanguage = Settings.Language;
            _compactMode = Settings.CompactMode;
        }
    }

    private string GetPreviewStyle()
    {
        var bg = _selectedTheme switch
        {
            "Dark" => "background-color: #1e1e1e; color: #e0e0e0;",
            "System" => "background-color: #f0f0f0; color: #333;",
            _ => "background-color: #ffffff; color: #333;"
        };
        var font = _selectedFontSize switch
        {
            "Small" => "font-size: 0.85rem;",
            "Large" => "font-size: 1.2rem;",
            _ => "font-size: 1rem;"
        };
        var padding = _compactMode ? "padding: 0.5rem;" : "padding: 1.5rem;";
        return $"{bg} {font} {padding} border: 1px solid #ccc; border-radius: 8px; margin-top: 1rem;";
    }

    private async Task Save()
    {
        var settings = new AppearanceSettings(_selectedTheme, _selectedFontSize, _selectedLanguage, _compactMode);
        await OnSave.InvokeAsync(settings);
    }
}

